using System;using System.IO;using System.Reflection;using System.Runtime.InteropServices;using System.Collections.Generic;using System.Windows.Forms;using System.Web.Script.Serialization;
class GaugeFeedProbe {
[DllImport("kernel32.dll")]static extern IntPtr GetModuleHandle(string name);
[DllImport("kernel32.dll")]static extern IntPtr VirtualAlloc(IntPtr p,UIntPtr size,uint kind,uint protection);
[DllImport("kernel32.dll")]static extern bool VirtualFree(IntPtr p,UIntPtr size,uint kind);
[UnmanagedFunctionPointer(CallingConvention.StdCall)]delegate int NativeCall();
static int InvokeRegister(IntPtr self,int edx,IntPtr target){var p=VirtualAlloc(IntPtr.Zero,(UIntPtr)32,0x3000,0x40);if(p==IntPtr.Zero)throw new Exception("Thunk allocation");try{var b=new List<byte>();b.Add(0xb8);b.AddRange(BitConverter.GetBytes(self.ToInt32()));b.Add(0xba);b.AddRange(BitConverter.GetBytes(edx));b.Add(0xb9);b.AddRange(BitConverter.GetBytes(target.ToInt32()));b.AddRange(new byte[]{0xff,0xd1,0xc3});Marshal.Copy(b.ToArray(),0,p,b.Count);return ((NativeCall)Marshal.GetDelegateForFunctionPointer(p,typeof(NativeCall)))();}finally{VirtualFree(p,UIntPtr.Zero,0x8000);}}static void SetPosition(IntPtr self,IntPtr target,double value){var p=VirtualAlloc(IntPtr.Zero,(UIntPtr)64,0x3000,0x40);try{var b=new List<byte>();b.Add(0xb8);b.AddRange(BitConverter.GetBytes(self.ToInt32()));byte[] d=BitConverter.GetBytes(value);b.Add(0x68);b.AddRange(new byte[]{d[4],d[5],d[6],d[7]});b.Add(0x68);b.AddRange(new byte[]{d[0],d[1],d[2],d[3]});b.AddRange(new byte[]{0x6a,0,0x6a,0});b.Add(0xb9);b.AddRange(BitConverter.GetBytes(target.ToInt32()));b.AddRange(new byte[]{0xff,0xd1,0xc3});Marshal.Copy(b.ToArray(),0,p,b.Count);((NativeCall)Marshal.GetDelegateForFunctionPointer(p,typeof(NativeCall)))();}finally{VirtualFree(p,UIntPtr.Zero,0x8000);}}static BindingFlags flags=BindingFlags.Instance|BindingFlags.NonPublic;
static void Call(object h,string n){typeof(TrainerIntegrationHost).GetMethod(n,flags).Invoke(h,null);}
static float F(IntPtr p,int o){byte[] b=new byte[4];Marshal.Copy(IntPtr.Add(p,o),b,0,4);return BitConverter.ToSingle(b,0);}
static double D(IntPtr p,int o){byte[] b=new byte[8];Marshal.Copy(IntPtr.Add(p,o),b,0,8);return BitConverter.ToDouble(b,0);}
[STAThread]static int Main(){Application.EnableVisualStyles();var h=(TrainerIntegrationHost)Activator.CreateInstance(typeof(TrainerIntegrationHost),true);var csv=new System.Text.StringBuilder("cycle,model_pm,arrow_pm,model_tm,arrow_tm\n");try{IntPtr handle=h.Handle;Call(h,"StartNative");((Timer)typeof(TrainerIntegrationHost).GetField("timer",flags).GetValue(h)).Stop();var mem=(Dictionary<string,IntPtr>)typeof(TrainerIntegrationHost).GetField("mem",flags).GetValue(h);var cars=(IntPtr[])typeof(TrainerIntegrationHost).GetField("cars",flags).GetValue(h);var cab=Marshal.ReadIntPtr(mem["CommOwner"],0x2bc);var module=GetModuleHandle("Communication1.dll");if(module==IntPtr.Zero)throw new Exception("Communication module absent");InvokeRegister(cab,1,IntPtr.Add(module,2812308));var tumba=Marshal.ReadIntPtr(cab,0x10);if(tumba==IntPtr.Zero)throw new Exception("Tumba wrapper not instantiated");var form=Marshal.ReadIntPtr(tumba,0xc);var control=Marshal.ReadIntPtr(form,0x3a4);if(control==IntPtr.Zero)throw new Exception("VCU control absent");foreach(float tmPressure in new float[]{5f,.7f})foreach(float impulse in new float[]{0f,4f}){Marshal.Copy(BitConverter.GetBytes(tmPressure),0,cars[0],4);Marshal.Copy(BitConverter.GetBytes(impulse),0,IntPtr.Add(mem["TLocParam"],13),4);Marshal.Copy(BitConverter.GetBytes((double)impulse),0,IntPtr.Add(mem["TLocParam"],0xec),8);Marshal.WriteByte(mem["TLocParam"],0x8f,1);Call(h,"ElectricalCycle");Marshal.WriteByte(control,0x220,0);SetPosition(control,IntPtr.Add(module,0x2a4944),1d);bool locked=tmPressure>=.8f||impulse<=3f;Marshal.WriteByte(control,0x220,(byte)(locked?1:0));Marshal.WriteInt32(control,0x224,1);Marshal.WriteByte(control,0x228,1);Console.WriteLine("pre VCU="+Marshal.ReadByte(mem["TLocParam"],0x8f)+" nestedCurrent="+Marshal.ReadInt32(Marshal.ReadIntPtr(control,0x210),0x88)+" validate2="+(InvokeRegister(control,2,IntPtr.Add(module,0x2a4a80))&255)+" validate3="+(InvokeRegister(control,3,IntPtr.Add(module,0x2a4a80))&255));SetPosition(control,IntPtr.Add(module,0x2a4944),3d);byte accepted=Marshal.ReadByte(mem["TLocParam"],0x8f);if(accepted!=(locked?1:3))throw new Exception("Candidate gate mismatch tm="+tmPressure+" pressure="+impulse+" actual="+accepted);Console.WriteLine("accepted="+accepted+" "+"TM="+tmPressure+" IM_fixture="+impulse+" blocked="+Marshal.ReadByte(control,0x220)+" limit="+Marshal.ReadInt32(control,0x224)+" direction="+Marshal.ReadByte(control,0x228)+" allow3="+(InvokeRegister(control,2,IntPtr.Add(module,0x2a4a80))&255));}return 0;}catch(Exception ex){Console.WriteLine(ex);return 1;}finally{h.Close();h.Dispose();}}
}







